export function recommendMoneyTrack(score){return score<=1?'explorer':score===2?'strategist':'architect'}
export function runMoneyPlan(steps){return steps.map(x=>x.answer)}
export function moneyChoiceIndex(seed,count){let hash=0;for(const char of seed)hash=(hash*31+char.charCodeAt(0))>>>0;return hash%count}
export function freshMoneyChoiceIndex(trackId,kind,step,challenge,count){const base=moneyChoiceIndex(`${trackId}:fresh:${kind}:${step}`,count);return challenge?(base+1)%count:base}
export function createBlankMoneyLearner(){return{track:null,activeMission:0,diagnostic:{index:0,score:0,answers:[]},missions:{},sessions:{},evidence:{budget:'unknown',tradeoff:'unknown',repair:'unknown',transfer:'unknown'},retestDue:null,previewFresh:false,family:{help:'',explain:'',continue:''},updatedAt:null}}
